import{_ as n,B as o,o as t,c as r,ax as s,b as l,w as i,a as c,E as d,ah as h}from"./chunks/framework.Bnt0oLax.js";const w=JSON.parse('{"title":"Key Concepts","description":"Plain-English definitions and mental model of Developer Studio — what Extensions (widgets, scripts, stylesheets), connectors, secrets, and the publishing pipeline are and how they relate, with runtime mechanics covered in Widget Runtime","frontmatter":{"description":"Plain-English definitions and mental model of Developer Studio — what Extensions (widgets, scripts, stylesheets), connectors, secrets, and the publishing pipeline are and how they relate, with runtime mechanics covered in Widget Runtime"},"headers":[],"relativePath":"getting-started/concepts.md","filePath":"getting-started/concepts.md"}'),p={name:"getting-started/concepts.md"};function u(g,e,m,f,y,b){const a=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=s(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/getting-started/concepts.md for this page in Markdown format</div><h1 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h1><p>Developer Studio is built around a small set of interconnected ideas. Understanding how they relate helps you make better decisions as you build. This page explains each concept and why it works the way it does.</p><h2 id="extension" tabindex="-1">Extension <a class="header-anchor" href="#extension" aria-label="Permalink to &quot;Extension&quot;">​</a></h2><p>An <strong>Extension</strong> is anything you publish to your community from a code repository. There are three kinds — <strong>widgets</strong>, <strong>scripts</strong>, and <strong>stylesheets</strong> — and you declare all of them in a single file, <code>extensions_registry.json</code>, at the root of your repository. They share one registry, one publishing pipeline, and one set of page-targeting rules, so you ship any combination you need.</p><p>The three types differ in what they do: a widget is a placed, configurable component; a script is global JavaScript; a stylesheet is global CSS. The sections below define each in turn.</p><p><a href="/docs/custom-widgets/v2/">Extensions</a></p><h2 id="widget" tabindex="-1">Widget <a class="header-anchor" href="#widget" aria-label="Permalink to &quot;Widget&quot;">​</a></h2><p>A self-contained component that appears on a community page. Widgets can display text, images, charts, forms, or any HTML content. They are placed onto pages using the <strong>No-Code Builder</strong>.</p><p>Widgets can be <strong>built-in</strong> (provided by the platform) or <strong>custom</strong> (created by your team from HTML/CSS/JS code stored in a Git repository). Custom widgets run inside Shadow DOM, which isolates their styles and markup from the rest of the page — so your widget&#39;s CSS never conflicts with the community theme, and the theme never overrides your styles.</p><h2 id="script" tabindex="-1">Script <a class="header-anchor" href="#script" aria-label="Permalink to &quot;Script&quot;">​</a></h2><p>A <strong>script</strong> is global JavaScript that runs across your community pages, independent of any single widget. Where a widget is one component in one page zone, a script applies to every matching page — use it for analytics, tracking, or shared utilities. You declare each script in the <code>scripts</code> array of <code>extensions_registry.json</code> and choose where it loads on the page.</p><p><a href="/docs/custom-widgets/v2/scripts-overview.html">Scripts Overview</a></p><h2 id="stylesheet" tabindex="-1">Stylesheet <a class="header-anchor" href="#stylesheet" aria-label="Permalink to &quot;Stylesheet&quot;">​</a></h2><p>A <strong>stylesheet</strong> is global CSS that applies across your community pages, independent of any single widget. Unlike a widget&#39;s styles — which stay isolated inside its Shadow DOM — a global stylesheet reaches the whole page and every element on it, so use it for sitewide theming, fonts, and design tokens. You declare each stylesheet in the <code>stylesheets</code> array of <code>extensions_registry.json</code>.</p><p><a href="/docs/custom-widgets/v2/stylesheets-overview.html">Stylesheets Overview</a></p><h2 id="no-code-builder" tabindex="-1">No-Code Builder <a class="header-anchor" href="#no-code-builder" aria-label="Permalink to &quot;No-Code Builder&quot;">​</a></h2><p>The visual editor inside your community. Community managers use it to drag and drop widgets onto pages, rearrange them, and configure their settings — all without writing code.</p><p>When a custom widget is published, it automatically appears in the No-Code Builder&#39;s widget library, ready to be added to any page.</p><h2 id="connector" tabindex="-1">Connector <a class="header-anchor" href="#connector" aria-label="Permalink to &quot;Connector&quot;">​</a></h2><p>A secure, reusable configuration for calling an external API. Widget code runs in the browser, so making API calls directly would expose API keys and tokens to anyone using your community. Connectors solve this by routing requests through the platform&#39;s backend, where secrets are injected server-side — the browser never sees the credentials.</p><p>Each connector defines a <strong>destination URL</strong>, an <strong>HTTP method</strong>, <strong>authentication</strong> settings, and optional <strong>headers</strong>, <strong>query parameters</strong>, and <strong>payload templates</strong>. Once created, you call a connector from widget code using its unique <strong>permalink</strong>. The platform handles the rest: resolving secrets, applying authentication, forwarding the request, and returning the response.</p><p><a href="/docs/connectors/">Learn more about Connectors</a></p><h2 id="secret" tabindex="-1">Secret <a class="header-anchor" href="#secret" aria-label="Permalink to &quot;Secret&quot;">​</a></h2><p>A securely stored credential — such as an API key, token, or client secret — that connectors use for authentication. Secrets are managed through the platform UI and referenced in connector configurations using the <code>get_secret()</code> function in <a href="https://jinja.palletsprojects.com/" target="_blank" rel="noreferrer">Jinja2</a> templates. They are never exposed to the browser.</p><p><a href="/docs/connectors/secrets/">Secrets and Variables</a></p><h2 id="variable" tabindex="-1">Variable <a class="header-anchor" href="#variable" aria-label="Permalink to &quot;Variable&quot;">​</a></h2><p>A reusable, plain-text configuration value — such as a base URL, environment identifier, or instance ID — that connectors use for non-sensitive settings. Variables are managed through the platform UI and referenced in connector configurations using the <code>get_variable()</code> function in <a href="https://jinja.palletsprojects.com/" target="_blank" rel="noreferrer">Jinja2</a> templates. Unlike secrets, variables are visible and can be used in a connector&#39;s URL, so you can point the same connector at different environments. Never store credentials in a variable.</p><p><a href="/docs/connectors/secrets/#variables">Secrets and Variables</a></p><h2 id="sdk-widget-sdk" tabindex="-1">SDK (Widget SDK) <a class="header-anchor" href="#sdk-widget-sdk" aria-label="Permalink to &quot;SDK (Widget SDK)&quot;">​</a></h2><p>A JavaScript library that widget code uses to interact with the platform. Its primary use is calling connectors from inside a widget — a call like <code>sdk.connectors.execute(...)</code> runs a connector and returns its response, so the browser never sees your credentials.</p><p><a href="/docs/sdk/">SDK</a></p><h2 id="extensions-registry" tabindex="-1">Extensions Registry <a class="header-anchor" href="#extensions-registry" aria-label="Permalink to &quot;Extensions Registry&quot;">​</a></h2><p>The <code>extensions_registry.json</code> file at the root of your code repository. It declares every Extension you publish — the <strong>widgets</strong>, <strong>scripts</strong>, and <strong>stylesheets</strong> in that repository — in three top-level arrays. Each array is optional, so you publish only the types you need.</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;widgets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scripts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;stylesheets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>For the full field specification of each entry type, see the <a href="/docs/custom-widgets/v2/registry-reference.html">Registry Reference</a>.</p><h2 id="publishing-pipeline" tabindex="-1">Publishing Pipeline <a class="header-anchor" href="#publishing-pipeline" aria-label="Permalink to &quot;Publishing Pipeline&quot;">​</a></h2><p>The automated process that turns code in your repository into live Extensions. When you push to a watched branch, the platform detects the change, fetches your files, validates them against security rules, and publishes them — typically in seconds. This push-to-publish model means there is no manual deploy step: your Git workflow <em>is</em> your deployment workflow. The trade-off is that anything pushed to the watched branch goes live immediately, which is why separate staging communities exist for pre-production testing.</p><p><a href="/docs/custom-widgets/v2/build-and-publish.html">Build &amp; Publish</a></p><h2 id="content-security" tabindex="-1">Content Security <a class="header-anchor" href="#content-security" aria-label="Permalink to &quot;Content Security&quot;">​</a></h2><p>Because custom Extensions run real code inside your community, the platform checks every push for security issues before publishing. Scans detect patterns like crypto mining, data exfiltration, phishing, obfuscated code, and exposed credentials. Builds that contain flagged content are rejected — previously published content remains live until a clean push succeeds. This means a bad push never takes down existing widgets; it blocks the update.</p><p><a href="/docs/custom-widgets/v2/content-security.html">Content Security</a></p><h2 id="permalink" tabindex="-1">Permalink <a class="header-anchor" href="#permalink" aria-label="Permalink to &quot;Permalink&quot;">​</a></h2><p>A URL-friendly identifier automatically generated from a connector&#39;s name. For example, a connector named &quot;Weather API&quot; gets the permalink <code>weather-api</code>. You use this permalink when calling the connector from widget code.</p><h2 id="branch-based-environments" tabindex="-1">Branch-Based Environments <a class="header-anchor" href="#branch-based-environments" aria-label="Permalink to &quot;Branch-Based Environments&quot;">​</a></h2><p>A workflow where different Git branches serve different versions of your Extensions to different communities. Each repository watches one branch at a time per community — switching the branch replaces all Extensions from that repository. Use separate communities (dev, staging, production) to run multiple environments from the same repository without interfering with each other.</p><div class="warning custom-block"><p class="custom-block-title">Production impact</p><p>Changing the watched branch takes effect immediately for all users of that community. Never switch the watched branch to test changes — use a separate staging community instead.</p></div><p><a href="/docs/custom-widgets/recipes/preview-and-promote.html">Preview and Promote</a></p><h2 id="how-it-all-fits-together" tabindex="-1">How It All Fits Together <a class="header-anchor" href="#how-it-all-fits-together" aria-label="Permalink to &quot;How It All Fits Together&quot;">​</a></h2><p>A typical workflow touches most of these concepts: you define a <strong>widget</strong> in the <strong>Extensions Registry</strong>, push to a watched branch, the <strong>Publishing Pipeline</strong> validates and publishes it, and it appears in the <strong>No-Code Builder</strong>. If the widget needs external data, you create a <strong>Connector</strong> with <strong>Secrets</strong> for authentication and call it via the <strong>SDK</strong>. <strong>Branch-Based Environments</strong> let you preview safely before going live, and <strong>Content Security</strong> ensures nothing harmful reaches your community.</p>`,50)),(t(),l(h,null,{default:i(()=>[d(a,{id:"mermaid-148",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20community%5B%22Your%20Community%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20builder%5B%22Pages%20built%20with%20the%20No-Code%20Builder%22%5D%0A%20%20%20%20%20%20%20%20builder%20--%3E%20w1%5B%22Widget%22%5D%20%26%20w2%5B%22Widget%22%5D%20%26%20w3%5B%22Widget%22%5D%0A%20%20%20%20%20%20%20%20w1%20--%3E%20c1%5B%22Connector%22%5D%0A%20%20%20%20%20%20%20%20w2%20--%3E%20c2%5B%22Connector%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20c1%20--%20%22Secure%20backend%20proxy%22%20--%3E%20sf%5B%22Salesforce%22%5D%0A%20%20%20%20c2%20--%20%22Secure%20backend%20proxy%22%20--%3E%20weather%5B%22Weather%20API%22%5D%0A%0A%20%20%20%20style%20community%20fill%3A%23f5f9fc%2Cstroke%3A%2339a2ff%2Cstroke-width%3A2px%2Ccolor%3A%23132436%0A%20%20%20%20style%20builder%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20w1%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20w2%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20w3%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20c1%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20c2%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20sf%20fill%3A%23dcfce7%2Cstroke%3A%2322c55e%2Ccolor%3A%231e293b%0A%20%20%20%20style%20weather%20fill%3A%23dcfce7%2Cstroke%3A%2322c55e%2Ccolor%3A%231e293b%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/docs/custom-widgets/v2/build-first-widget.html">Your First Widget</a> — hands-on widget tutorial</li><li><a href="/docs/custom-widgets/v2/first-script.html">Your First Script</a> — hands-on script tutorial</li><li><a href="/docs/custom-widgets/v2/first-stylesheet.html">Your First Stylesheet</a> — hands-on stylesheet tutorial</li><li><a href="/docs/connectors/build-first-connector.html">Build Your First Connector</a> — hands-on tutorial for connectors</li><li><a href="/docs/custom-widgets/v2/">Extensions</a> — all guides and reference for widgets, scripts, and stylesheets</li><li><a href="/docs/connectors/">Connectors</a> — all guides and reference for external API integration</li><li><a href="/docs/custom-widgets/v2/registry-reference.html">Registry Reference</a> — the <code>extensions_registry.json</code> root object</li></ul>',2))])}const v=n(p,[["render",u]]);export{w as __pageData,v as default};
